import type { StepPassage, StepQuestion } from './stepBank'

export const READING_PASSAGES: StepPassage[] = [
  { id: "r3", section: 'reading', title: "Sleep and Memory", text: "Many students believe that staying up all night before an exam is the best way to prepare. Research, however, suggests the opposite. While we sleep, the brain does not simply rest; it sorts through the information gathered during the day and moves the important parts into long-term memory.\n\nIn one well-known experiment, two groups learned the same list of words. One group slept for eight hours afterwards, while the other stayed awake. The next day, the group that had slept remembered far more words. Sleep also helps us concentrate, since tired people find it harder to pay attention. For this reason, scientists advise students to review their notes in the evening and then go to bed at a reasonable hour." },
  { id: "r4", section: 'reading', title: "The Story of Coffee", text: "According to a popular legend, coffee was discovered in Ethiopia by a goat herder named Kaldi, who noticed that his goats became unusually lively after eating the red berries of a certain bush. Whether or not the story is true, coffee was certainly being grown in Yemen by the fifteenth century, and from there it spread across the Arab world.\n\nCoffeehouses soon became popular meeting places where people played chess, listened to music, and discussed the news. Some were even nicknamed \"schools of the wise\" because of the conversations held inside them. By the seventeenth century, coffee had reached Europe, where it was first viewed with suspicion by some religious leaders but quickly won over ordinary people. Today it is one of the most widely traded products in the world." },
  { id: "r5", section: 'reading', title: "Gardening in the City", text: "In crowded cities, green space is rare, but a growing number of residents are finding creative ways to grow their own food. Balconies are covered with pots of herbs, rooftops host rows of vegetables, and empty pieces of land are turned into community gardens where neighbours work side by side.\n\nUrban gardening offers several benefits. Fresh vegetables taste better and cost less than those bought in shops, and plants help to cool the air during hot summers. Gardens also bring neighbours together, which can make a neighbourhood feel safer and friendlier. Nevertheless, there are challenges. Space is limited, and soil in some areas may contain pollution left by old factories, so gardeners often have to bring in clean soil or use raised beds." },
  { id: "r6", section: 'reading', title: "Are Electric Cars the Future?", text: "Electric cars have moved from being a rare curiosity to a common sight on many roads. They produce no exhaust fumes, which helps to keep city air cleaner, and they are cheap to run because electricity costs less than petrol. They also have fewer moving parts than traditional engines, so they usually need less maintenance.\n\nStill, they are not perfect. Batteries are expensive and take a long time to charge compared with filling a petrol tank, and in many regions there are not enough charging stations. Critics also point out that an electric car is only as clean as the electricity that powers it: if the power comes from coal, the overall benefit to the environment is smaller. Most experts believe, therefore, that improving the way we produce electricity is just as important as building more electric vehicles." },
  { id: "r7", section: 'reading', title: "The Silk Road", text: "The Silk Road was not a single road but a vast network of trade routes that connected China with the Mediterranean world for more than a thousand years. Merchants rarely travelled the whole distance. Instead, goods were passed from one trader to another, with each person selling to the next for a profit.\n\nSilk was the most famous product, but travellers also carried spices, paper, glass, and precious metals. The routes were just as important for the exchange of ideas. Religions, scientific knowledge, and artistic styles travelled alongside the goods, and cities along the way, such as Samarkand, grew rich and diverse. The name \"Silk Road\" itself is fairly modern; it was first used by a German geographer in the nineteenth century." },
  { id: "r8", section: 'reading', title: "Learning Never Stops", text: "Gone are the days when people studied only in their youth and then spent the rest of their lives working. Today, many adults return to learning to change careers, improve their skills, or simply follow their interests. This idea is known as lifelong learning.\n\nThe benefits are clear. Workers who keep learning are more likely to find better jobs, because technology changes quickly and employers value people who can adapt. Researchers also report that mentally active adults tend to stay healthier in old age. Even so, many adults say that they lack the time or money to study. Online courses have helped to solve this problem by allowing people to learn at their own pace, often at a low cost, from their own homes." },
  { id: "r9", section: 'reading', title: "Plastic in Our Oceans", text: "Every year, millions of tonnes of plastic waste end up in the world's oceans. Bottles, bags, and fishing nets float on the surface or sink to the bottom, where they can remain for hundreds of years. Over time, sunlight and waves break them into tiny pieces known as microplastics.\n\nThese fragments are a serious danger to marine life. Turtles may mistake plastic bags for jellyfish, and seabirds often feed their chicks pieces of plastic that look like food. Scientists have even found microplastics in fish that people eat. Solving the problem is not easy, but many countries have begun to ban single-use items such as plastic straws, while individuals can help by recycling and by choosing reusable bottles and bags." },
  { id: "r10", section: 'reading', title: "Teenagers and Social Media", text: "Social media has become a central part of teenage life. Young people use it to chat with friends, share photos, and discover new interests. For shy teenagers, it can even make it easier to start conversations and build friendships.\n\nHowever, researchers have raised several concerns. Teenagers who spend many hours online often compare themselves with the carefully chosen images they see, which can lower their confidence. Late-night scrolling also cuts into sleep, leaving students tired at school. Most experts do not suggest banning social media altogether. Instead, they recommend setting time limits, switching off notifications in the evening, and talking openly with parents about what happens online." },
  { id: "r11", section: 'reading', title: "The Great Barrier Reef", text: "Off the northeast coast of Australia lies the Great Barrier Reef, the largest coral reef system on Earth. It is so enormous that it can be seen from space, and it is made up of thousands of individual reefs and hundreds of islands. The reef is home to an extraordinary variety of life, including colourful fish, sea turtles, and many kinds of sharks.\n\nCorals are tiny animals that depend on microscopic algae living inside them for food and colour. When the sea becomes too warm, the corals push out the algae and turn white, a process called bleaching. Bleached corals can recover if the water cools quickly, but repeated events may kill them. Because of this, scientists are closely watching ocean temperatures and urging governments to reduce the pollution that causes global warming." },
  { id: "r12", section: 'reading', title: "Why Team Sports Matter", text: "Team sports such as football, basketball, and volleyball offer far more than physical exercise. Players learn to cooperate with others, to follow rules, and to accept different roles within a group. A talented striker, for example, cannot score without teammates who pass the ball to him.\n\nSport also teaches young people how to deal with disappointment. Losing a match can be painful, but players soon learn that effort and practice, not luck, lead to improvement. Critics warn, however, that too much pressure from parents and coaches can spoil the pleasure of playing. When winning becomes the only goal, children may lose interest or even quit. Most educators therefore argue that enjoyment should come first, especially at a young age." },
  { id: "r13", section: 'reading', title: "Is the World Running Out of Water?", text: "Although water covers most of our planet, only a tiny part of it is fresh water that people can drink or use for farming. Much of this fresh water is frozen in glaciers or lies deep underground. As the world's population grows, demand is rising fast, and many regions already struggle to supply enough clean water for their people.\n\nAgriculture is by far the biggest user, taking roughly seventy percent of the fresh water that humans withdraw. Therefore, saving water on farms can have a huge effect. Methods such as drip irrigation deliver water straight to the roots of plants and waste very little. Cities can also help by repairing leaking pipes, while some dry coastal countries turn seawater into drinking water, although this process is expensive and uses a lot of energy." },
  { id: "r14", section: 'reading', title: "The Printing Press", text: "Before the fifteenth century, books in Europe were copied by hand, usually by monks, and a single volume could take months to finish. As a result, books were rare and expensive, and only the wealthy and the clergy owned them. Around 1440, a German goldsmith named Johannes Gutenberg developed a machine that used movable metal letters to print pages quickly.\n\nThe effect was dramatic. Books became cheaper and far more common, and within a few decades presses were operating in cities across Europe. More people learned to read, and new ideas in science, religion, and politics spread much faster than before. Historians often rank the printing press among the most important inventions in history because it changed the way knowledge was shared." },
  { id: "r15", section: 'reading', title: "Ibn Battuta, the Great Traveller", text: "Ibn Battuta was born in Tangier, Morocco, in 1304. At the age of twenty-one he set out on a pilgrimage to Mecca, intending to return home within a couple of years. Instead, the journey became a way of life. Over the next thirty years he travelled through North Africa, the Middle East, Persia, India, Central Asia, and even parts of China, covering well over a hundred thousand kilometres.\n\nAlong the way he worked as a judge, advised rulers, and met scholars and ordinary people. When he finally returned to Morocco, the local sultan asked him to describe his adventures, and a scholar wrote them down in a book known as the Rihla. Although some historians question a few details, the book remains an invaluable record of life in the fourteenth-century world." },
  { id: "r16", section: 'reading', title: "The Problem of Noise", text: "We usually think of pollution as dirty air or water, but noise can also harm our health. People who live near busy roads, railways, or airports are exposed to constant sound, and over time this can raise stress levels, disturb sleep, and even increase the risk of heart problems. Children who attend noisy schools may also find it harder to learn.\n\nFortunately, there are practical solutions. Planners can build walls beside motorways, use road surfaces that absorb sound, and plant rows of trees. Some cities limit night flights or ban heavy lorries from residential streets. At home, people can help by lowering the volume of music and televisions, especially at night. The key, experts say, is to treat noise as a real problem rather than an unavoidable part of city life." },
  { id: "r17", section: 'reading', title: "Going Cashless", text: "In some countries, it is now possible to go through an entire day without touching a banknote. People pay for coffee with their phones, buy train tickets online, and even give small donations to street musicians using a scanning code. Supporters of the cashless society say this is faster, cleaner, and safer, since thieves have less money to steal.\n\nYet not everyone is happy about the change. Older people may find digital payments confusing, and visitors from abroad sometimes discover that shops will not accept their cash. Others worry about privacy because every payment leaves a record. There is also the risk of power or network failures, which can leave shoppers unable to buy anything. For these reasons, some governments have introduced laws requiring shops to accept cash as well." },
  { id: "r18", section: 'reading', title: "Breakfast and Learning", text: "Teachers have long noticed that children who arrive at school hungry often struggle to pay attention. Studies appear to support this observation. Pupils who eat breakfast tend to concentrate better, remember more, and behave more calmly during morning lessons than those who skip the meal.\n\nThe type of breakfast matters, too. A bowl of sugary cereal may give a quick burst of energy, but it wears off quickly and leaves the child hungry again before lunchtime. Foods such as eggs, whole-grain bread, and fruit release energy more slowly. Because some families cannot afford a morning meal, many schools now provide free breakfast, and early results suggest that attendance and grades have improved as a result." },
  { id: "r19", section: 'reading', title: "Holidays in Space?", text: "Once the dream of science fiction writers, space tourism is slowly becoming a reality. Several private companies now offer flights to the edge of space, where passengers can experience a few minutes of weightlessness and see the curve of the Earth. A small number of wealthy travellers have also spent days on orbiting space stations.\n\nThe cost, however, is enormous. A single seat can cost hundreds of thousands of dollars or more, so for the time being only the very rich can afford it. Critics argue that the money would be better spent on problems on Earth, and that rocket launches add pollution to the atmosphere. Supporters reply that competition between companies is making rockets cheaper and safer, and that the technology developed may eventually benefit everyone." },
  { id: "r20", section: 'reading', title: "Languages in Danger", text: "There are about seven thousand languages spoken in the world today, but linguists warn that nearly half of them could disappear by the end of this century. Most of these languages are spoken by small communities and have never been written down. When the last elderly speakers die, a whole way of describing the world may vanish with them.\n\nLanguages usually decline because younger people move to cities and choose to speak a dominant language such as English or Spanish, which offers better chances of finding work. Some communities are fighting back. They record stories and songs, create dictionaries, and teach the language to children in special schools. Experts point out that such efforts succeed only when young people see a practical use for the language in their daily lives." },
  { id: "r21", section: 'reading', title: "The Bilingual Brain", text: "Speaking two languages is not simply a useful skill; it also appears to change the way the brain works. Bilingual people must constantly decide which language to use and which to ignore, and this daily exercise seems to strengthen the part of the brain that controls attention. Studies have found that bilingual children are often better at switching between tasks and ignoring distractions.\n\nSome research even suggests that using two languages throughout life can delay the symptoms of memory-related illnesses by several years. Scientists are careful, however, not to overstate these results, because many factors affect brain health, including education and lifestyle. Still, nobody denies that learning another language opens doors to new cultures, friendships, and job opportunities, whatever its effect on the brain." },
  { id: "r22", section: 'reading', title: "The Cost of Cheap Clothes", text: "Fashion trends once changed with the seasons, but today some shops bring new designs to their stores every week. This \"fast fashion\" model makes clothes so cheap that many people buy far more than they need and throw them away after wearing them only a few times.\n\nThe environmental cost is high. Growing cotton requires huge amounts of water, and factories release chemical dyes into rivers. Much of the discarded clothing ends up in landfill, where synthetic fabrics may take decades to break down. Campaigners encourage shoppers to buy fewer, better-made items, to repair what they own, and to swap or buy second-hand clothes. Some brands have also begun using recycled materials, although critics say these efforts are still too small." },
  { id: "r23", section: 'reading', title: "Life at the Bottom of the World", text: "Antarctica is the coldest, driest, and windiest continent on Earth. Temperatures can fall below minus eighty degrees Celsius, and strong winds sweep across ice that is, in places, several kilometres thick. No one lives there permanently; the only inhabitants are scientists and support staff who stay at research stations for a few months or a year.\n\nIn 1959, a group of countries signed the Antarctic Treaty, which reserves the continent for peaceful purposes and scientific research. Scientists drill deep into the ice to extract long cylinders called ice cores. Trapped air bubbles inside them reveal what the atmosphere was like hundreds of thousands of years ago, helping researchers to understand how the climate has changed. Because Antarctica is so remote, it is also one of the few places left almost untouched by human activity." },
  { id: "r24", section: 'reading', title: "The Ancient and Modern Olympics", text: "The first Olympic Games were held in Olympia, Greece, more than two thousand seven hundred years ago, in honour of the god Zeus. They took place every four years, and during the games, wars between Greek city-states were paused so that athletes and spectators could travel safely. The earliest event was a running race, but others such as wrestling and chariot racing were added later.\n\nThe ancient Games ended in the fourth century, but they were revived in 1896, when a French educator named Pierre de Coubertin organised the first modern Olympics in Athens. About two hundred and forty athletes from fourteen nations took part. Since then, the event has grown into the world's largest sporting competition, with thousands of athletes from over two hundred countries, and women have competed since 1900." },
  { id: "r25", section: 'reading', title: "Why Do We Dream?", text: "Every night, most people experience several dreams, though they usually remember only a few. The most vivid dreams occur during a stage of sleep called REM, when the eyes move rapidly beneath the closed lids and the brain is almost as active as when we are awake.\n\nScientists have proposed several explanations for dreaming. Some believe dreams help the brain to process emotions, which may explain why stressful days often lead to troubling dreams. Others think dreaming helps to sort and store memories, while a further group suggests that dreams are simply a by-product of random brain activity. At the beginning of the twentieth century, Sigmund Freud argued that dreams reveal hidden wishes, but most modern researchers consider this idea unproven. In fact, no single theory has yet been accepted by everyone." },
  { id: "r26", section: 'reading', title: "Understanding Earthquakes", text: "The surface of the Earth is made up of huge slabs of rock called tectonic plates, which move very slowly, usually only a few centimetres each year. Where two plates meet, they sometimes become stuck. Pressure builds until the rock suddenly breaks, releasing energy in waves that shake the ground. This is an earthquake.\n\nScientists cannot yet predict exactly when or where an earthquake will happen, but they know which regions are most at risk. In those areas, engineers design buildings that can bend slightly without collapsing, and schools hold regular drills teaching children to drop to the floor, cover their heads, and hold on to something sturdy. Most injuries during earthquakes are caused not by the shaking itself but by falling objects and damaged buildings, so preparation can save many lives." },
  { id: "r27", section: 'reading', title: "The Rise of Online Shopping", text: "Twenty years ago, buying a pair of shoes meant visiting a shop, trying them on, and carrying them home. Today, millions of people simply click a button and wait for a delivery. Online shopping has grown quickly because it saves time, offers a wider choice, and lets customers compare prices in seconds.\n\nThis convenience has a price, however. Many small local shops have closed because they cannot compete with large websites. Delivery vans add to traffic and pollution, and returned items often end up in waste. Shoppers also face risks such as fake websites that steal bank details. Experts advise buyers to use trusted sites, read reviews carefully, and avoid deals that seem too good to be true." },
  { id: "r28", section: 'reading', title: "Trees Make Cities Cooler", text: "Concrete, asphalt, and glass absorb heat during the day and release it slowly at night, which makes city centres several degrees warmer than the surrounding countryside. This effect, known as the \"urban heat island\", can make summer heatwaves dangerous, especially for the elderly.\n\nTrees offer a simple and attractive solution. Their leaves provide shade, and they also release water vapour, which cools the air around them in a similar way to sweat cooling our skin. A street with many trees can be noticeably cooler than one without. In addition, trees absorb pollution, reduce noise, and make neighbourhoods more pleasant. Several cities have therefore launched large tree-planting programmes, although they must choose species that can survive in small spaces and in dry weather." },
  { id: "r29", section: 'reading', title: "How Were the Pyramids Built?", text: "The Great Pyramid of Giza was built about four and a half thousand years ago for the pharaoh Khufu. It originally stood about one hundred and forty-six metres tall and was made of more than two million blocks of stone. For centuries, it was the tallest human-made structure on Earth.\n\nFor a long time, people imagined that enormous crowds of slaves were forced to build it. Archaeologists now believe otherwise. Excavations near the site uncovered the remains of workers' towns, bakeries, and tombs, which suggest that the builders were paid labourers who were fed well and given medical care. The workers probably moved the blocks on wooden sledges, pouring water on the sand in front to make it easier to pull them. Even so, many details of the construction remain a mystery, and scholars continue to study the site." },
  { id: "r30", section: 'reading', title: "Why Public Transport Matters", text: "A single bus can carry as many passengers as forty or fifty cars, which makes public transport one of the most efficient ways to move people around a city. When more people use buses, trams, and trains, there are fewer cars on the road, so traffic jams shrink and the air becomes cleaner.\n\nDespite these advantages, many people still prefer to drive. They complain that buses are unreliable, that stations are far from their homes, and that tickets are expensive. Cities that have succeeded in attracting passengers usually did several things at once: they ran vehicles more frequently, built dedicated bus lanes so that buses are not stuck in traffic, and introduced a single ticket that works on every service. In short, people use public transport when it is faster and easier than driving." },
  { id: "r31", section: 'reading', title: "Power from the Desert", text: "Deserts receive more energy from the sun in a few hours than the entire world uses in a year. With few clouds, empty land, and strong sunshine, they appear to be ideal places for solar power. Huge solar farms have already been built in several desert regions, supplying electricity to millions of homes.\n\nThere are, however, practical difficulties. Dust and sand can cover the panels and reduce their efficiency, so they must be cleaned regularly, which is a problem in places where water is scarce. In addition, deserts are often far from the cities that need the power, and building long cables is costly. Some engineers are experimenting with waterless cleaning robots, and others are developing batteries that store energy for use at night. If these ideas succeed, deserts could become major energy suppliers." },
  { id: "r32", section: 'reading', title: "Why We Put Things Off", text: "Almost everyone has delayed an important task, such as studying for an exam or writing a report, in favour of something more enjoyable. Psychologists call this habit procrastination, and contrary to popular belief, it has little to do with laziness. Instead, it is mostly an attempt to avoid unpleasant feelings such as worry, boredom, or fear of failure.\n\nThe trouble is that avoiding a task offers only temporary relief. The deadline comes closer, stress rises, and the work is often completed in a hurry and with poor quality. Experts suggest breaking large tasks into small steps and starting with just five minutes of work; once we begin, the task often seems less frightening. Setting a clear time and place for studying and removing distractions such as phones can also help." },
  { id: "r33", section: 'reading', title: "A Brief History of Chocolate", text: "Chocolate began as a bitter drink, not a sweet treat. Ancient peoples in Central America, including the Maya and Aztecs, prepared a frothy beverage from roasted cacao beans, water, and spices. The Aztecs valued the beans so highly that they were sometimes used as money.\n\nSpanish explorers brought cacao to Europe in the sixteenth century, where people began adding sugar to improve the taste. For about three hundred years, chocolate remained an expensive drink enjoyed mainly by the rich. Everything changed in the nineteenth century, when new machines made it possible to produce solid chocolate in large quantities and at lower prices. Soon afterwards, manufacturers invented milk chocolate, and the product we know today was born." },
  { id: "r34", section: 'reading', title: "Introverts and Extroverts", text: "Psychologists often divide people into introverts and extroverts. Extroverts feel energised by company; they enjoy parties, talk easily with strangers, and may feel bored when alone. Introverts, on the other hand, gain energy from quiet time. They usually prefer small groups or one-to-one conversations and need time alone to recover after a busy day.\n\nIt is a mistake, however, to think that introverts are simply shy. Shyness is a fear of being judged, while introversion is just a preference for quieter surroundings. Moreover, most people are not at either extreme; they fall somewhere in the middle and behave differently depending on the situation. Schools and workplaces that offer both group activities and quiet spaces allow every kind of personality to do their best work." },
  { id: "r35", section: 'reading', title: "Robots in the Factory", text: "Industrial robots first appeared in car factories in the 1960s, where they performed dangerous and repetitive tasks such as welding and lifting heavy parts. Today, robots are found in almost every industry. They can work around the clock without getting tired, and they make fewer mistakes than humans on precise tasks.\n\nNot everyone welcomes this change. Workers fear that machines will take their jobs, and indeed some roles have disappeared. Economists point out, though, that technology has also created new occupations, such as robot programmers, maintenance engineers, and data analysts. The challenge for governments and companies is to retrain workers so that they can move into these new roles. Otherwise, the benefits of automation may reach only a small part of society." },
  { id: "r36", section: 'reading', title: "Climbing Mount Everest", text: "At 8,849 metres above sea level, Mount Everest is the highest mountain on Earth. It was first climbed in 1953 by Edmund Hillary of New Zealand and Tenzing Norgay, a Sherpa from Nepal. Since then, thousands of people have reached the summit, helped by improved equipment, weather forecasts, and the skills of local Sherpa guides.\n\nSuccess, however, is never guaranteed. Climbers face extreme cold, strong winds, and a lack of oxygen that can cause dizziness and confusion. Crowds have also become a problem: in the short period of good weather each spring, long queues form near the top, and waiting in the thin air can be dangerous. In addition, rubbish left by earlier expeditions has built up on the slopes, and Nepalese authorities now require climbers to bring their waste back down." },
  { id: "r37", section: 'reading', title: "Museums Go Digital", text: "Visiting a museum used to mean standing in front of a glass case and reading a small label. Today, many museums offer interactive screens, audio guides on smartphones, and virtual tours that allow people to explore galleries from their own homes. Some even use three-dimensional scans so that visitors can examine ancient objects from every angle.\n\nSupporters say that technology makes museums accessible to people who cannot travel, including students in distant villages and visitors with disabilities. It can also protect fragile artefacts, because digital copies can be handled freely while the originals remain safely stored. Critics, however, fear that screens may distract visitors from the real objects. They argue that nothing can replace the experience of standing in front of an artwork or an object that is thousands of years old." },
  { id: "r38", section: 'reading', title: "Handwriting or Typing?", text: "As keyboards and touchscreens replace pens and paper, some teachers worry that handwriting may soon become a lost skill. Research suggests this might be a mistake. In several studies, students who took notes by hand understood and remembered lectures better than those who typed them.\n\nOne explanation is that handwriting is slower. Since students cannot write every word, they must listen carefully and choose the most important ideas, a process that deepens understanding. Typists, by contrast, often copy the lecture word for word without thinking about it. Even so, typing has clear advantages: it is faster, legible, and easy to search and edit. The best approach may therefore be to use both methods, handwriting for learning and keyboards for producing finished documents." },
  { id: "r39", section: 'reading', title: "The Amazon Rainforest", text: "The Amazon is the largest rainforest in the world, stretching across nine countries in South America, with the greatest part lying in Brazil. It is home to an astonishing variety of life: scientists believe that roughly one in ten of all known species lives there, from tiny insects to jaguars and river dolphins.\n\nThe forest also plays an important role in the global climate, because its trees store enormous amounts of carbon that would otherwise add to global warming. Sadly, large areas are cut down every year to create farmland and pastures for cattle. When forest is lost, animals lose their homes and the stored carbon is released into the air. Conservation groups are working with local communities and governments to protect the remaining forest and to find ways for people to earn a living without destroying it." },
  { id: "r40", section: 'reading', title: "Managing Your Study Time", text: "Many students say they do not have enough time to study, yet researchers who track how students spend their days often find that hours are lost to small distractions. Checking messages, moving between tasks, and waiting until the last minute all reduce the time available for real work.\n\nEffective students usually follow a few simple habits. They write a weekly timetable that includes lessons, study sessions, and rest. They divide study time into short periods, typically about forty-five minutes, with brief breaks in between, because concentration drops after long stretches of work. Finally, they deal with the most difficult subject first, when their minds are fresh. Learning to manage time is not about working harder; it is about using the hours you already have more wisely." },
  { id: "r41", section: 'reading', title: "Heat from Underground", text: "Iceland sits on a boundary between two tectonic plates, which means that hot rock lies close to the surface and heats water deep underground. Icelanders have learned to use this natural resource, known as geothermal energy. Hot water is pumped through pipes to warm homes, melt snow on pavements, and heat swimming pools and greenhouses, where vegetables can be grown even in the cold climate.\n\nGeothermal power plants also produce electricity, and together with hydropower they supply almost all of Iceland's electricity without burning fossil fuels. Not every country can copy this success, however, because geothermal heat is only easy to reach in volcanic regions. Engineers are, nevertheless, developing new drilling methods that may allow more places to use heat from the Earth in the future." },
  { id: "r42", section: 'reading', title: "The Joy of Street Food", text: "Walk through almost any city in the world and you will smell it before you see it: food cooked on the street. In Cairo, vendors sell hot ful and falafel sandwiches from small carts; in Bangkok, noodles sizzle in giant pans; in Mexico City, people queue for tacos. Street food is usually cheap, tasty, and ready in minutes, which makes it popular with workers and students.\n\nIt is also an important part of local culture. Recipes are passed from parents to children, and a single stall may become famous for a special sauce or a secret mixture of spices. Street vending provides jobs for thousands of families, too. The main concern is hygiene. To avoid illness, health experts advise customers to choose busy stalls, where food is cooked fresh and quickly sold, and to look for vendors who keep their equipment clean." },
  { id: "r43", section: 'reading', title: "Fitness Trackers", text: "Wristbands and smartwatches that count steps, measure heart rate, and monitor sleep have become extremely popular. Their supporters say they make it easier to stay active. Seeing a daily total on a screen can motivate people to take a longer walk, and sharing results with friends adds a friendly sense of competition.\n\nThe devices are not perfect, though. Their measurements can be inaccurate, especially for calories and sleep stages, and some users become anxious when numbers are lower than expected. There are also questions about privacy, since companies that collect health data may use or sell it. Doctors therefore suggest treating a tracker as a helpful guide rather than a medical tool, and consulting a professional if the figures cause real concern." },
  { id: "r44", section: 'reading', title: "The Nile and Egyptian Farming", text: "For thousands of years, Egyptian civilisation has depended on the Nile, the longest river in Africa. Each summer, rain in the highlands far to the south caused the river to flood. When the water receded, it left a layer of dark, fertile silt on the fields, and farmers could grow wheat, barley, and vegetables without needing much fertiliser.\n\nIn 1970, the Aswan High Dam was completed, and it changed this pattern. The dam controls the flow of water, protecting the country from both destructive floods and severe droughts, and its power station supplies electricity to millions of homes. On the other hand, the silt now settles behind the dam instead of reaching the fields, so many farmers have to use artificial fertiliser to keep the soil productive. Engineers continue to look for ways to balance the needs of farmers, cities, and the environment." },
  { id: "r45", section: 'reading', title: "Staying Safe Online", text: "Every day, millions of people log in to email, banking, and social media accounts using passwords. Yet many still choose passwords that are easy to guess, such as their name or a simple sequence of numbers. Criminals use programs that can try thousands of combinations in a few seconds, so weak passwords offer almost no protection.\n\nSecurity experts give clear advice. A strong password should be long, preferably a phrase of several unrelated words, and different for each account, so that a leak from one website does not endanger the others. Because remembering many passwords is difficult, a password manager can store them safely. Wherever possible, users should also switch on two-step verification, which requires a code sent to a phone in addition to the password. Finally, never click links in unexpected messages, since these are often attempts to steal personal details." },
  { id: "r46", section: 'reading', title: "The Value of Volunteering", text: "Every year, millions of people give their time without payment to help others: they serve meals at shelters, teach children to read, clean beaches, or support hospitals. Volunteers often say that they receive as much as they give. Helping others can create a sense of purpose, build friendships, and lift a person's mood.\n\nVolunteering can also be a practical step towards a career. Young people who have little work experience can learn skills such as teamwork, communication, and organisation, and employers often look favourably on such activities. The biggest obstacle is usually time, since study and work leave little space for anything else. For this reason, many organisations now offer flexible opportunities, such as a few hours at weekends or tasks that can be done online." },
  { id: "r47", section: 'reading', title: "Living with Less", text: "Minimalism is a lifestyle based on a simple idea: own only the things that are useful or that you truly love. Followers of the movement clear out cupboards, give away unused items, and think carefully before making new purchases. Many say that a tidier home leads to a calmer mind and that spending less money gives them greater freedom, including the freedom to change jobs or travel.\n\nCritics, however, argue that minimalism is not realistic for everyone. A family with young children, for example, naturally needs many belongings, and people on low incomes often keep items because they cannot afford to replace them. Some also complain that minimalism has turned into a fashionable style, with expensive \"simple\" products. Perhaps the most useful lesson is not to own as little as possible, but to be thoughtful about what we buy and why." },
  { id: "r48", section: 'reading', title: "More than Books", text: "When people hear the word \"library\", they imagine quiet rooms filled with shelves of books. Modern libraries, however, offer much more. Many provide free internet access and computers for people who have none at home. Others run language classes, homework clubs, and workshops for job seekers, and some even lend tools, musical instruments, and board games.\n\nFor children, libraries are a safe and welcoming place to discover reading, and storytelling sessions help young visitors to develop their language skills. For adults, they are a source of reliable information in an age when much online content is unreliable. Despite these advantages, many libraries face budget cuts, and some have had to reduce their opening hours or close entirely. Supporters argue that this would be a mistake, because a library serves the whole community at a very low cost." },
  { id: "r49", section: 'reading', title: "Artificial Intelligence in Medicine", text: "Hospitals around the world are beginning to use artificial intelligence to help doctors. One of the most promising uses involves medical images. After studying thousands of X-rays or scans, a computer program can learn to notice tiny signs of disease that a tired human eye might miss, which allows doctors to start treatment earlier.\n\nOther programs help hospitals to schedule operations, keep track of medicines, and answer patients' routine questions. Nevertheless, many experts urge caution. A program can only be as good as the information used to train it, and mistakes could be serious. Patients' private data must also be kept secure. Most doctors agree that artificial intelligence should support, not replace, human professionals, since caring for patients also requires kindness and judgement that no machine can provide." },
  { id: "r50", section: 'reading', title: "Surviving in the Desert", text: "The camel is often called the \"ship of the desert\", and with good reason. Contrary to a common belief, its hump does not store water; it stores fat, which the animal can use as energy when food is scarce. A camel can survive for days without drinking, and when water is available, it can drink a huge amount in just a few minutes.\n\nIts body has many other adaptations. Thick eyelashes and nostrils that can close protect it from blowing sand, while wide, padded feet stop it from sinking into soft ground. Its thick coat keeps the sun's heat away from its skin, and it sweats very little, so it loses water slowly. For centuries, these abilities made camels invaluable to people crossing the desert, carrying goods and passengers across enormous distances." },
]

